-- MOD-17 / MOD-34: barangay coordination (BARANGAY_ALERT_AUTOMATION_PLAN.md, Phase 1).
--
-- Adds the data foundation for telling the BDRRMC/BPSO of the barangay an incident
-- falls in: barangay boundaries, a contact directory, a per-incident notice record
-- and an inbound-SMS log. No incident status or role is added: barangay involvement
-- lives on its own rows and never changes the incident lifecycle.
--
-- Hand-written SQL (like 20261013120000_add_geo_regions) because geo_regions uses a
-- PostGIS column and several constraints below are partial indexes / CHECKs that
-- Prisma cannot express.

-- ── Enums ────────────────────────────────────────────────────────────────────

CREATE TYPE "barangay_contact_kind" AS ENUM ('MOBILE', 'LANDLINE');
CREATE TYPE "barangay_contact_role" AS ENUM ('PRIMARY', 'BACKUP', 'OTHER');
CREATE TYPE "barangay_match_method" AS ENUM ('POLYGON', 'NEAREST', 'MANUAL');
CREATE TYPE "barangay_sms_status" AS ENUM ('PENDING', 'SENT', 'PARTIAL', 'FAILED', 'SKIPPED', 'DISABLED');
CREATE TYPE "barangay_report_type" AS ENUM ('ON_THE_WAY', 'HANDLED', 'NEEDS_BACKUP', 'NO_ANSWER');
CREATE TYPE "barangay_report_source" AS ENUM ('SMS_REPLY', 'PHONE_CALL');
CREATE TYPE "barangay_inbound_outcome" AS ENUM (
  'APPLIED', 'DUPLICATE', 'UNKNOWN_SENDER', 'UNKNOWN_CODE', 'NOT_NOTIFIED', 'UNPARSED', 'DISABLED'
);

-- ── geo_regions: allow multi-part barangay shapes ───────────────────────────
-- The municipality row stays as-is (wrapped as a one-part MultiPolygon), so the
-- geo-fence query in AuthService.checkGeoFence keeps working unchanged.

ALTER TABLE "geo_regions"
  ALTER COLUMN "boundary" TYPE geometry(MultiPolygon, 4326) USING ST_Multi("boundary");

-- ── barangay_contacts ───────────────────────────────────────────────────────

CREATE TABLE "barangay_contacts" (
    "id"          UUID NOT NULL DEFAULT uuid_generate_v4(),
    "barangay_id" TEXT NOT NULL,
    "phone_e164"  VARCHAR(16) NOT NULL,
    "phone_raw"   VARCHAR(40),
    "kind"        "barangay_contact_kind" NOT NULL,
    "can_sms"     BOOLEAN NOT NULL DEFAULT false,
    "role"        "barangay_contact_role" NOT NULL DEFAULT 'OTHER',
    "label"       VARCHAR(120),
    "is_active"   BOOLEAN NOT NULL DEFAULT true,
    -- Temporary demo data. Production alerting must refuse to text these.
    "is_demo"     BOOLEAN NOT NULL DEFAULT false,
    "verified_at" TIMESTAMPTZ(6),
    "source"      VARCHAR(120),
    "created_at"  TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at"  TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "barangay_contacts_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "barangay_contacts_phone_e164_chk" CHECK ("phone_e164" ~ '^\+63[0-9]{9,10}$'),
    -- A landline cannot receive the gateway's SMS.
    CONSTRAINT "barangay_contacts_sms_kind_chk" CHECK (NOT "can_sms" OR "kind" = 'MOBILE'),
    -- Alert targets (PRIMARY / BACKUP) must be reachable by SMS.
    CONSTRAINT "barangay_contacts_alert_role_chk" CHECK ("role" = 'OTHER' OR "can_sms")
);

CREATE UNIQUE INDEX "uq_barangay_contacts_phone" ON "barangay_contacts"("barangay_id", "phone_e164");
-- At most one active PRIMARY and one active BACKUP per barangay.
CREATE UNIQUE INDEX "uq_barangay_contacts_one_primary" ON "barangay_contacts"("barangay_id")
  WHERE "role" = 'PRIMARY' AND "is_active";
CREATE UNIQUE INDEX "uq_barangay_contacts_one_backup" ON "barangay_contacts"("barangay_id")
  WHERE "role" = 'BACKUP' AND "is_active";
CREATE INDEX "idx_barangay_contacts_barangay_active" ON "barangay_contacts"("barangay_id", "is_active");

ALTER TABLE "barangay_contacts"
  ADD CONSTRAINT "barangay_contacts_barangay_id_fkey"
  FOREIGN KEY ("barangay_id") REFERENCES "geo_regions"("id") ON DELETE RESTRICT ON UPDATE NO ACTION;

-- ── incident_barangay_notices ───────────────────────────────────────────────
-- One row per incident per barangay: who was told, by which SMS, and what came back.

CREATE TABLE "incident_barangay_notices" (
    "id"                    UUID NOT NULL DEFAULT uuid_generate_v4(),
    "incident_id"           UUID NOT NULL,
    "barangay_id"           TEXT NOT NULL,
    "match_method"          "barangay_match_method" NOT NULL,
    "is_approximate"        BOOLEAN NOT NULL DEFAULT false,
    "short_code"            VARCHAR(4) NOT NULL,
    "sms_status"            "barangay_sms_status" NOT NULL DEFAULT 'PENDING',
    "sms_sent_at"           TIMESTAMPTZ(6),
    "last_report"           "barangay_report_type",
    "last_report_source"    "barangay_report_source",
    "last_report_at"        TIMESTAMPTZ(6),
    "last_report_by_user_id" UUID,
    "followup_due_at"       TIMESTAMPTZ(6),
    "followup_sent_at"      TIMESTAMPTZ(6),
    "closed_at"             TIMESTAMPTZ(6),
    "created_at"            TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at"            TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "incident_barangay_notices_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "incident_barangay_notices_short_code_chk" CHECK ("short_code" ~ '^[0-9]{4}$'),
    CONSTRAINT "incident_barangay_notices_report_chk"
      CHECK (("last_report" IS NULL) = ("last_report_at" IS NULL))
);

CREATE UNIQUE INDEX "uq_incident_barangay_notices_incident_barangay"
  ON "incident_barangay_notices"("incident_id", "barangay_id");
-- A short code identifies one OPEN notice; it is reusable once the notice closes.
CREATE UNIQUE INDEX "uq_incident_barangay_notices_open_code"
  ON "incident_barangay_notices"("short_code") WHERE "closed_at" IS NULL;
CREATE INDEX "idx_incident_barangay_notices_incident" ON "incident_barangay_notices"("incident_id");
CREATE INDEX "idx_incident_barangay_notices_barangay" ON "incident_barangay_notices"("barangay_id", "created_at" DESC);
CREATE INDEX "idx_incident_barangay_notices_followup"
  ON "incident_barangay_notices"("followup_due_at")
  WHERE "closed_at" IS NULL AND "followup_sent_at" IS NULL;

ALTER TABLE "incident_barangay_notices"
  ADD CONSTRAINT "incident_barangay_notices_incident_id_fkey"
  FOREIGN KEY ("incident_id") REFERENCES "incidents"("id") ON DELETE CASCADE ON UPDATE NO ACTION;
ALTER TABLE "incident_barangay_notices"
  ADD CONSTRAINT "incident_barangay_notices_barangay_id_fkey"
  FOREIGN KEY ("barangay_id") REFERENCES "geo_regions"("id") ON DELETE RESTRICT ON UPDATE NO ACTION;
ALTER TABLE "incident_barangay_notices"
  ADD CONSTRAINT "incident_barangay_notices_last_report_by_user_id_fkey"
  FOREIGN KEY ("last_report_by_user_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE NO ACTION;

-- ── barangay_sms_inbound ────────────────────────────────────────────────────
-- Append-only log of every SMS received from a barangay, applied or not. Application
-- code only INSERTs. provider_message_id makes webhook retries and re-polls idempotent.

CREATE TABLE "barangay_sms_inbound" (
    "id"                  UUID NOT NULL DEFAULT uuid_generate_v4(),
    "provider_message_id" VARCHAR(100) NOT NULL,
    "from_phone"          VARCHAR(32) NOT NULL,
    "from_phone_e164"     VARCHAR(16),
    "body"                TEXT NOT NULL,
    "received_at"         TIMESTAMPTZ(6) NOT NULL,
    "parsed_command"      VARCHAR(12),
    "parsed_code"         VARCHAR(4),
    "notice_id"           UUID,
    "outcome"             "barangay_inbound_outcome" NOT NULL,
    "created_at"          TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "barangay_sms_inbound_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "uq_barangay_sms_inbound_provider_message" ON "barangay_sms_inbound"("provider_message_id");
CREATE INDEX "idx_barangay_sms_inbound_notice" ON "barangay_sms_inbound"("notice_id");
CREATE INDEX "idx_barangay_sms_inbound_received" ON "barangay_sms_inbound"("received_at" DESC);

ALTER TABLE "barangay_sms_inbound"
  ADD CONSTRAINT "barangay_sms_inbound_notice_id_fkey"
  FOREIGN KEY ("notice_id") REFERENCES "incident_barangay_notices"("id") ON DELETE SET NULL ON UPDATE NO ACTION;

