ON CONFLICT ("id") DO UPDATE SET
  "name" = EXCLUDED."name",
  "region_type" = EXCLUDED."region_type",
  "boundary" = EXCLUDED."boundary",
  "last_updated_at" = now();

-- ── Safety checks: fail the whole migration rather than ship bad boundaries ─

DO $$
DECLARE
  barangay_count INTEGER;
BEGIN
  SELECT count(*) INTO barangay_count FROM "geo_regions" WHERE "region_type" = 'barangay';
  IF barangay_count <> 19 THEN
    RAISE EXCEPTION 'barangay_coordination: expected 19 barangay regions, found %', barangay_count;
  END IF;

  IF EXISTS (
    SELECT 1 FROM "geo_regions"
    WHERE "region_type" = 'barangay' AND (NOT ST_IsValid("boundary") OR ST_IsEmpty("boundary"))
  ) THEN
    RAISE EXCEPTION 'barangay_coordination: a barangay boundary is invalid or empty';
  END IF;

  -- The municipal geo-fence row must have survived the column change.
  IF NOT EXISTS (
    SELECT 1 FROM "geo_regions" WHERE "name" = 'Bocaue' AND "region_type" = 'municipality'
  ) THEN
    RAISE EXCEPTION 'barangay_coordination: municipality geo-fence row is missing';
  END IF;
END $$;
